def _ld_safe(s):
    """JSON placed inside <script>: "</" must not appear raw, or a value holding
    "</script>" (e.g. a submitted business name) would end the block early.
    "<\\/" parses to the same JSON, so pages are unchanged for normal data."""
    return s.replace("</", "<\\/")

