# ── Listing overrides from the admin panel (D1, read via leaderboard Worker) ────
# Admin panel: https://esr-admin.surinamedomains.workers.dev (Cloudflare Access).
# Overrides win over JSON; applied before anything reads _BIZ. Build never fails
# on backend trouble — it just ships without overrides.
_OVR_FIELDS = ("description", "website", "phone", "address", "facebook")
# 23 Oct 2026: the Listings tab also edits name, email, district, opening hours and
# map pin. Each value is checked again here, so a bad row is skipped instead of
# reaching a page; a blank name/district/hours/pin means "no override".
_OVR_DISTRICTS = ("Paramaribo", "Wanica", "Commewijne", "Nickerie", "Sipaliwini", "Para",
                  "Marowijne", "Brokopondo", "Saramacca", "Coronie", "Suriname")
_OVR_DAY = r"(?:Mo|Tu|We|Th|Fr|Sa|Su)"
_OVR_TR = r"(?:[01]\d|2[0-3]):[0-5]\d-(?:(?:[01]\d|2[0-3]):[0-5]\d|24:00)"
_OVR_HOURS_RE = re.compile(_OVR_DAY + r"(?:[-,]" + _OVR_DAY + r")*\s+" + _OVR_TR + r"(?:," + _OVR_TR + r")*")


def _ovr_hours_ok(v):
    if v == "24/7":
        return True
    rules = [r.strip() for r in v.split(";")]
    return all(r in ("PH off", "PH closed") or _OVR_HOURS_RE.fullmatch(r) for r in rules) and \
        any(r not in ("PH off", "PH closed") for r in rules)


def _ovr_apply(slug, o):
    """Apply one admin-panel override row to _BIZ[slug] (and the hours map)."""
    b = _BIZ[slug]
    for _ok in _OVR_FIELDS:
        if isinstance(o.get(_ok), str):
            b[_ok] = o[_ok].strip()
    _v = o.get("name")
    if isinstance(_v, str) and _v.strip() and len(_v.strip()) <= 120 and not re.search(r"[<>]", _v):
        b["name"] = _v.strip()
    _v = o.get("email")
    if isinstance(_v, str) and (not _v.strip() or
                                re.fullmatch(r"[^@\s<>\"']+@[^@\s<>\"']+\.[A-Za-z]{2,}", _v.strip())):
        b["email"] = _v.strip()
    _v = o.get("location")
    if isinstance(_v, str) and _v.strip() in _OVR_DISTRICTS:
        b["location"] = _v.strip()
    _v = o.get("hours")
    if isinstance(_v, str) and _v.strip() and len(_v) <= 300 and _ovr_hours_ok(_v.strip()):
        b["hours"] = _v.strip()
        _MANUAL_HOURS[slug] = _v.strip()      # admin beats JSON, OSM and the hand-set entries
    _v = o.get("geo")
    if isinstance(_v, str) and _v.strip():
        try:
            _la, _lo = (float(x) for x in _v.split(","))
            if 1.5 <= _la <= 6.5 and -58.5 <= _lo <= -53.5:
                b["geo"] = f"{_la:.5f},{_lo:.5f}"
        except Exception:
            pass


# Backend feeds keep a last good copy (23 Oct 2026). One timeout on all three feeds
# (12:35 SR build) shipped the site for one build without community events, submitted
# listings and admin edits. Each feed is now tried twice; every good answer is saved in
# data/feed_cache/ (committed with data/), and that copy is used when the backend does
# not answer. Returns (data, live). Raises only when there is no answer and no copy.
_FEED_CACHE_DIR = Path(__file__).parent / "data" / "feed_cache"


def _feed_get(url, name):
    import urllib.request as _fq
    import time as _ft
    _last = None
    for _i, _t in enumerate((15, 20)):
        try:
            _rq = _fq.Request(url, headers={"User-Agent": "ExploreSR-build/1.0"})
            with _fq.urlopen(_rq, timeout=_t) as _rs:
                _raw = _rs.read()
            _data = json.loads(_raw.decode("utf-8"))
            try:
                _FEED_CACHE_DIR.mkdir(parents=True, exist_ok=True)
                _cp = _FEED_CACHE_DIR / (name + ".json")
                if not _cp.exists() or _cp.read_bytes() != _raw:
                    _cp.write_bytes(_raw)
            except Exception as _ce:
                print(f"  Warning: could not save the {name} feed copy — {_ce}")
            return _data, True
        except Exception as _fe:
            _last = _fe
            if _i == 0:
                _ft.sleep(3)
    _cp = _FEED_CACHE_DIR / (name + ".json")
    if _cp.exists():
        _data = json.loads(_cp.read_text(encoding="utf-8"))
        _age = datetime.fromtimestamp(_cp.stat().st_mtime, timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        print(f"  Warning: {name} feed unavailable ({_last}); using the last good copy ({_age})")
        return _data, False
    raise _last


