_CHAIN_OF      = {}   # member slug -> brand
_CHAIN_PRIMARY = {}   # brand -> hub slug
for _cbrand, _cmem in _CHAIN_GROUPS.items():
    _CHAIN_PRIMARY[_cbrand] = _cmem[0]
    for _cs in _cmem:
        _CHAIN_OF[_cs] = _cbrand


def _branch_label(brand, b):
    """Short chip label: whatever distinguishes this address from the brand."""
    n = (b.get("name") or "").strip()
    m = re.fullmatch(re.escape(brand) + r"\s*\((.+)\)", n, re.I)
    if m:
        return m.group(1).strip()
    if n.lower().startswith(brand.lower()) and len(n) > len(brand):
        rest = n[len(brand):].strip(" -\u2013\u2014:,")
        if rest:
            return rest
    addr = (b.get("address") or "").split(",")[0].strip()
    area = (b.get("area") or "").strip()
    if addr and addr.lower() != area.lower() and len(addr) <= 34:
        return addr
    return area or "Main branch"


def _chain_members(brand):
    """Full biz dicts for every address of a chain, primary first."""
    return [x for x in (_make_biz(s) for s in _CHAIN_GROUPS.get(brand, [])) if x]


def _collapse_chains(lst):
    """Drop branch cards from a category grid, keep one card per brand."""
    out = []
    for b in lst:
        brand = _CHAIN_OF.get(b["slug"])
        if brand is None:
            out.append(b)
            continue
        if _CHAIN_PRIMARY[brand] != b["slug"]:
            continue   # a branch — its page stays, its card does not
        mem = _chain_members(brand)
        c = dict(b)
        c["name"]            = brand
        c["chain_count"]     = len(mem)
        c["chain_districts"] = sorted({x.get("area") or "Paramaribo" for x in mem})
        out.append(c)
    return out


# Sort every category list alphabetically by display name
# Grouped taxonomy (Oct 2026): chain branches follow the re-sorted type of
# their reviewed sibling, and no Services/Shopping item may keep a key its page
# does not offer (retired or foreign) — it would only show under "All".
for _cmem in _CHAIN_GROUPS.values():
    _ck = next((_RESORT_SUBCAT[_m] for _m in _cmem if _m in _RESORT_SUBCAT), None)
    if _ck:
        for _m in _cmem:
            _RESORT_SUBCAT.setdefault(_m, _ck)
_CAT_LEGACY_FIX = {"service": {"nursery-garden": "garden-pest",
                               # chain branches filed under the other page (Carline)
                               "auto-parts": "automotive", "car-dealers": "automotive"},
                   "shopping": {"automotive": "car-dealers"}, "restaurant": {}}
_subfix = []
for _lst, _gcat in ((SERVICES, "service"), (SHOPPING, "shopping"), (RESTAURANTS, "restaurant")):
    _valid = {_k for _k, _l, _i in SUBCATS[_gcat]} - SUBCAT_LEGACY[_gcat]
    for _b in _lst:
        _k = _subcat(_b["slug"])
        if _k not in _valid:
            _k = _CAT_LEGACY_FIX[_gcat].get(_k, "other")
            _RESORT_SUBCAT[_b["slug"]] = _k
            _subfix.append(_b["slug"])
        _b["subcat"] = _k
if _subfix:
    print(f"  Subcat safety net moved {len(_subfix)} listing(s): {', '.join(_subfix[:8])}")

