# -- Helpers ------------------------------------------------------------------

def strip_tags(text):
    if not text: return ""
    return html_lib.unescape(re.sub(r"<[^>]+>", " ", text)).strip()

# WordPress feeds append a footer to every summary: "Dit bericht <title> is
# afkomstig van <site>." (GFC Nieuws), "The post <title> appeared first on
# <site>.", "Het bericht <title> verscheen eerst op <site>." Cut it off.
_FEED_FOOTER_RE = re.compile(
    r"\s*(?:Dit bericht|Het bericht|The post)\b.{0,400}?\b(?:is afkomstig van|verscheen eerst op|appeared first on)\b.*$",
    re.S | re.I)


def clean_summary(text):
    t = _FEED_FOOTER_RE.sub("", text or "")
    return re.sub(r"\s+", " ", t).strip()


def get_image(entry):
    for attr in ("media_thumbnail", "media_content"):
        val = getattr(entry, attr, None)
        if val and isinstance(val, list):
            url = val[0].get("url", "")
            if url: return url
    if hasattr(entry, "enclosures"):
        for enc in entry.enclosures:
            if enc.get("type", "").startswith("image"):
                return enc.get("url", "")
    raw = (getattr(entry, "summary", "") or "") + " ".join(
        (c.get("value") or "") for c in (getattr(entry, "content", None) or []))
    for m in re.finditer(r'<img[^>]+?src=["\']([^"\']+)["\']', raw):
        u = m.group(1)
        # skip emoji sprites, tracking pixels and avatars
        if re.search(r"s\.w\.org/images/core/emoji|gravatar\.com|feeds\.feedburner|pixel|1x1|\.gif(?:\?|$)", u, re.I):
            continue
        return u
    return ""

def parse_date(entry):
    for attr in ("published_parsed", "updated_parsed"):
        val = getattr(entry, attr, None)
        if val:
            try: return datetime(*val[:6], tzinfo=timezone.utc)
            except: pass
    return datetime.fromtimestamp(0, tz=timezone.utc)

def time_ago(dt):
    secs = int((datetime.now(timezone.utc) - dt).total_seconds())
    if secs < 60:    return "just now"
    if secs < 3600:  return f"{secs//60}m ago"
    if secs < 86400: return f"{secs//3600}h ago"
    return f"{secs//86400}d ago"

def fetch_overpass(query, limit=12):
    try:
        url  = "https://overpass-api.de/api/interpreter"
        data = urllib.parse.urlencode({"data": query}).encode()
        req  = urllib.request.Request(url, data=data, headers={"User-Agent": "ExploreSuriname/1.0"})
        with urllib.request.urlopen(req, timeout=20) as r:
            result = json.loads(r.read().decode())
        pois = []
        for el in result.get("elements", []):
            tags = el.get("tags", {})
            name = tags.get("name") or tags.get("name:en", "")
            if not name or len(name) < 2: continue
            pois.append({
                "name":     name,
                "cuisine":  tags.get("cuisine", "").replace(";", " · ").title(),
                "category": tags.get("tourism", tags.get("amenity", "")).replace("_", " ").title(),
                "area":     tags.get("addr:city", tags.get("addr:suburb", "Paramaribo")),
                "desc":     tags.get("description", ""),
                "url":      tags.get("website", f"https://www.google.com/search?q={urllib.parse.quote(name + ' suriname')}"),
            })
            if len(pois) >= limit: break
        return pois
    except Exception as e:
        print(f"  Overpass error: {e}")
        return []

def merge_with_fallbacks(live, fallbacks, target=20):
    used = {r["name"].lower() for r in live}
    for fb in fallbacks:
        if len(live) >= target: break
        if fb["name"].lower() not in used:
            live.append(fb)
    return live

_OBIT_KEYWORDS = {
    "rouwberichten", "rouwadvertentie", "rouwkaart", "rouwbericht",
    "overlijden", "in memoriam", "obituar",
}

def _is_obituary(entry, title_lower):
    """Return True if the entry is an obituary / death notice."""
    if any(kw in title_lower for kw in _OBIT_KEYWORDS):
        return True
    # Check feedparser category tags (term field)
    for tag in getattr(entry, "tags", []):
        term = getattr(tag, "term", "").lower()
        if any(kw in term for kw in _OBIT_KEYWORDS):
            return True
    return False

def fetch_articles():
    articles = []
    for src in FEEDS:
        try:
            feed  = feedparser.parse(src["url"])
            count = 0
            for entry in feed.entries[:MAX_PER_FEED]:
                title   = strip_tags(getattr(entry, "title", "")).strip()
                # Skip obituaries/death notices (De Ware Tijd posts many)
                if _is_obituary(entry, title.lower()):
                    continue
                link    = getattr(entry, "link", "#")
                summary = clean_summary(strip_tags(getattr(entry, "summary", "")))
                if len(summary) > 200: summary = summary[:197] + "..."
                pub = parse_date(entry)
                articles.append({
                    "title": title, "link": link, "summary": summary,
                    "image": get_image(entry), "date": pub, "ago": time_ago(pub),
                    "source": src["name"], "color": src["color"],
                })
                count += 1
            print(f"  OK  {src['name']}: {count}")
        except Exception as e:
            print(f"  ERR {src['name']}: {e}")
    articles.sort(key=lambda a: a["date"], reverse=True)
    try:
        _news_enrich_images(articles)
    except Exception as e:          # images are a nice-to-have, never fatal
        print(f"  News images: skipped ({e})")
    return _news_archive_merge(articles)


def _news_link_key(u):
    """Normalise an article URL so RSS and WP REST links compare equal."""
    try:
        p = urllib.parse.urlsplit(urllib.parse.unquote((u or "").strip()))
        host = p.netloc.lower()
        host = host[4:] if host.startswith("www.") else host
        return host + p.path.rstrip("/").lower()
    except Exception:
        return (u or "").strip().lower()


def _news_wp_pick(media):
    """(image ~768px, thumb ~300px) from a WP featured-media object."""
    media = media or {}
    sizes = (media.get("media_details") or {}).get("sizes") or {}
    def _u(keys):
        for k in keys:
            v = (sizes.get(k) or {}).get("source_url")
            if v:
                return v
        return ""
    full = media.get("source_url") or ""
    img = _u(("medium_large", "large", "1536x1536")) or full
    thumb = _u(("medium", "medium_large")) or img
    return img, thumb


def _news_enrich_images(articles):
    """Fill "image"/"thumb" on local stories (see FEEDS note). In place."""
    from concurrent.futures import ThreadPoolExecutor
    _UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
    feeds = {f["name"]: f for f in FEEDS}

    # Images already known from earlier builds (no refetch for og: outlets)
    known = {}
    try:
        for r in json.loads(NEWS_ARCHIVE_PATH.read_text(encoding="utf-8")):
            if r.get("image"):
                known[r.get("link")] = (r["image"], r.get("thumb") or r["image"])
    except Exception:
        pass

    def _wp(f):
        url = (f["wp"] + "/wp-json/wp/v2/posts?per_page=40&_embed=wp:featuredmedia"
               "&_fields=id,link,_links,_embedded")
        req = urllib.request.Request(url, headers={"User-Agent": _UA, "Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=20) as r:
            posts = json.loads(r.read().decode("utf-8"))
        out = {}
        for p in posts if isinstance(posts, list) else []:
            media = ((p.get("_embedded") or {}).get("wp:featuredmedia") or [{}])[0]
            img, thumb = _news_wp_pick(media)
            if img and _feed_url(img, img=True):
                out[_news_link_key(p.get("link"))] = (img, thumb)
                if p.get("id"):
                    out["id:" + str(p["id"])] = (img, thumb)
        return f["name"], out

    wp_maps = {}
    with ThreadPoolExecutor(max_workers=6) as ex:
        for fut in [ex.submit(_wp, f) for f in FEEDS if f.get("wp")]:
            try:
                name, m = fut.result()
                wp_maps[name] = m
            except Exception as e:
                print(f"  News images: WP API failed ({e})")

    _og_re = re.compile(r'<meta[^>]+(?:property|name)=["\']og:image["\'][^>]*content=["\']([^"\']+)', re.I)
    _og_re2 = re.compile(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name)=["\']og:image["\']', re.I)
    def _og(link):
        req = urllib.request.Request(link, headers={"User-Agent": _UA})
        with urllib.request.urlopen(req, timeout=10) as r:
            page = r.read(400_000).decode("utf-8", "replace")
        m = _og_re.search(page) or _og_re2.search(page)
        u = html_lib.unescape(m.group(1)).strip() if m else ""
        if u.startswith("//"):
            u = "https:" + u
        # an outlet logo is not a story picture
        if not u or re.search(r"logo|default|placeholder", u, re.I) or not _feed_url(u, img=True):
            return link, ""
        return link, u

    wp_hit = og_hit = 0
    og_todo = []
    for a in articles:
        if a.get("image"):
            a.setdefault("thumb", a["image"])
            continue
        link = a.get("link") or ""
        if link in known:
            a["image"], a["thumb"] = known[link]
            continue
        f = feeds.get(a.get("source")) or {}
        m = wp_maps.get(a.get("source"))
        if m:
            hit = m.get(_news_link_key(link))
            if not hit:
                pid = re.search(r"[?&]p=(\d+)", link)
                hit = m.get("id:" + pid.group(1)) if pid else None
            if hit:
                a["image"], a["thumb"] = hit
                wp_hit += 1
                continue
        if f.get("og") and link.startswith("http"):
            og_todo.append(a)
    og_todo = og_todo[:NEWS_OG_MAX_PER_BUILD]
    if og_todo:
        by_link = {a["link"]: a for a in og_todo}
        with ThreadPoolExecutor(max_workers=6) as ex:
            for fut in [ex.submit(_og, a["link"]) for a in og_todo]:
                try:
                    link, u = fut.result()
                except Exception:
                    continue
                if u:
                    by_link[link]["image"] = by_link[link]["thumb"] = u
                    og_hit += 1
    have = sum(1 for a in articles if a.get("image"))
    print(f"  News images: {have}/{len(articles)} live stories ({wp_hit} via WP API, {og_hit} via og:image)")


def _news_archive_merge(live):
    """Merge this build's headlines with the rolling archive on disk.

    Returns the merged list (newest first) and rewrites data/news_archive.json.
    Live entries win over archived copies of the same link, because outlets
    edit titles and summaries after publishing.
    """
    now    = datetime.now(timezone.utc)
    cutoff = now - timedelta(days=NEWS_ARCHIVE_DAYS)
    epoch  = datetime.fromtimestamp(0, tz=timezone.utc)
    colors = {f["name"]: f["color"] for f in FEEDS}
    merged = {}

    def _keep(row, dt):
        link = (row.get("link") or "").strip()
        if not link or link == "#":
            return
        if dt <= epoch or dt < cutoff or dt > now + timedelta(hours=6):
            return          # missing/absurd dates would otherwise pin to the top
        row = dict(row)
        row["date"]  = dt
        row["color"] = colors.get(row.get("source"), row.get("color", "#374151"))
        old = merged.get(link)
        if old and old.get("image") and not row.get("image"):
            row["image"] = old["image"]
            row["thumb"] = old.get("thumb") or old["image"]
        merged[link] = row

    try:
        rows = json.loads(NEWS_ARCHIVE_PATH.read_text(encoding="utf-8"))
    except Exception:
        rows = []
    for r in rows if isinstance(rows, list) else []:
        try:
            dt = datetime.fromisoformat(r["date"])
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        _keep(r, dt)
    _archived = len(merged)

    for a in live:
        _keep(a, a["date"])

    out = sorted(merged.values(), key=lambda a: a["date"], reverse=True)[:NEWS_ARCHIVE_MAX]

    # Rewrite only when something actually changed — the site rebuilds every
    # ~15 min but the outlets do not publish that often, and an unchanged file
    # means no commit and no repo churn.
    _payload = json.dumps(
        [{k: (v.isoformat() if k == "date" else v)
          for k, v in a.items() if k != "ago"} for a in out],
        ensure_ascii=False, separators=(",", ":"))
    try:
        if _payload != NEWS_ARCHIVE_PATH.read_text(encoding="utf-8"):
            raise ValueError("changed")
    except Exception:
        try:
            NEWS_ARCHIVE_PATH.parent.mkdir(parents=True, exist_ok=True)
            NEWS_ARCHIVE_PATH.write_text(_payload, encoding="utf-8")
        except Exception as e:
            print(f"  News archive write failed: {e}")

    for a in out:            # "ago" is relative to build time, always recompute
        a["ago"] = time_ago(a["date"])

    _span = (now - out[-1]["date"]).total_seconds() / 3600 if out else 0
    print(f"  News archive: {len(live)} live + {_archived} stored -> "
          f"{len(out)} articles spanning {_span:.0f}h")
    return out

# ── Story clustering ────────────────────────────────────────────────────────
# Ten local outlets cover the same story, so the raw merged feed shows each
# event three to five times. Cluster near-duplicate headlines into one card and
# list the other outlets as "also covered by" links.

_NEWS_STOPWORDS = {
    # Dutch
    "aan", "als", "ander", "andere", "bij", "daar", "dan", "dat", "deze", "die",
    "dit", "door", "een", "eerste", "geen", "gaan", "gaat", "haar", "had", "heb",
    "hebben", "heeft", "het", "hier", "hij", "hoe", "hun", "iets", "kan", "komen",
    "komt", "kunnen", "maar", "meer", "meest", "met", "moet", "moeten", "naar",
    "niet", "nieuw", "nieuwe", "nog", "omdat", "onder", "ook", "over", "tegen",
    "toch", "tot", "tussen", "uit", "van", "veel", "voor", "waar", "want", "was",
    "wat", "weer", "wel", "werd", "worden", "wordt", "zeer", "zegt", "zich",
    "zijn", "zonder", "jaar", "jaren", "dag", "dagen", "week", "maand",
    # English
    "about", "after", "against", "and", "are", "been", "but", "for", "from",
    "has", "have", "into", "its", "more", "new", "not", "over", "said", "says",
    "that", "the", "their", "there", "they", "this", "was", "were", "what",
    "when", "where", "which", "will", "with", "year", "years",
}

# Dutch number words normalised to digits: two outlets writing "tien jaar cel"
# and "10 jaar cel" must produce the same token, because numbers are the
# strongest signal for telling two similar-sounding court cases apart.
_NEWS_NUM_WORDS = {
    "twee": "2", "drie": "3", "vier": "4", "vijf": "5", "zes": "6", "zeven": "7",
    "acht": "8", "negen": "9", "tien": "10", "elf": "11", "twaalf": "12",
    "dertien": "13", "veertien": "14", "vijftien": "15", "twintig": "20",
    "dertig": "30", "veertig": "40", "vijftig": "50", "honderd": "100",
    "duizend": "1000", "miljoen": "1000000", "miljard": "1000000000",
}

_NEWS_TOKEN_RE = re.compile(r"[a-z\u00e0-\u00ff]+|\d+(?:\.\d+)?")

def _news_tokens(title):
    """Content-word token set for headline similarity, numbers included."""
    t = (title or "").lower().replace("\u2019", "'")
    t = re.sub(r"(\d),(\d)", r"\1.\2", t)      # 2,5 jaar -> 2.5
    out = set()
    for w in _NEWS_TOKEN_RE.findall(t):
        if w[0].isdigit():
            out.add(w.rstrip(".").lstrip("0") or "0")
        elif w in _NEWS_NUM_WORDS:
            out.add(_NEWS_NUM_WORDS[w])
        elif len(w) >= 3 and w not in _NEWS_STOPWORDS:
            out.add(w)
    return out

def _news_idf(token_sets):
    """Inverse document frequency over the day's headlines.

    Plain word overlap merges unrelated stories, because Surinamese headlines
    share a lot of boilerplate ("OM eist ... jaar cel tegen ..."). Weighting by
    IDF makes the rare, story-defining words decide the match instead.
    """
    df = {}
    for toks in token_sets:
        for w in toks:
            df[w] = df.get(w, 0) + 1
    n = max(len(token_sets), 1)
    return {w: math.log(n / (1 + c)) + 0.15 for w, c in df.items()}

_NEWS_SIM_THRESHOLD    = 0.35   # weighted overlap needed to call it one story
_NEWS_SIM_NUM_CONFLICT = 0.65   # needed when the headlines disagree on numbers

def _news_same_story(a_toks, b_toks, idf):
    """True if two headlines almost certainly describe the same event."""
    if not a_toks or not b_toks:
        return False
    shared = a_toks & b_toks
    if len(shared) < 2:
        return False
    wa = sum(idf.get(w, 1.0) for w in a_toks)
    wb = sum(idf.get(w, 1.0) for w in b_toks)
    ws = sum(idf.get(w, 1.0) for w in shared)
    denom = min(wa, wb)
    if denom <= 0:
        return False
    score = ws / denom

    # Two reports of the same event almost always agree on at least one number.
    # Disagreeing numbers usually means two different cases, amounts or dates.
    a_nums = {w for w in a_toks if w[0].isdigit()}
    b_nums = {w for w in b_toks if w[0].isdigit()}
    if a_nums and b_nums and not (a_nums & b_nums):
        return score >= _NEWS_SIM_NUM_CONFLICT
    return score >= _NEWS_SIM_THRESHOLD

def cluster_articles(articles, window_hours=72):
    """Group near-duplicate stories across feeds.

    Input is the merged, newest-first article list. Returns the same dict shape
    with two extra keys so news_card_html can render them:
      also    - [{"source", "link", "color"}] for the other outlets
      sources - every source name in the cluster, representative first
    """
    clusters = []          # list of {"rep", "members", "toks"}
    seen_links = set()
    window = timedelta(hours=window_hours)
    idf = _news_idf([_news_tokens(a["title"]) for a in articles])

    for art in articles:
        link = (art.get("link") or "").strip()
        if link and link != "#":
            if link in seen_links:
                continue
            seen_links.add(link)
        toks = _news_tokens(art["title"])
        placed = False
        for c in clusters:
            if abs((c["rep"]["date"] - art["date"]).total_seconds()) > window.total_seconds():
                continue
            if _news_same_story(c["toks"], toks, idf):
                c["members"].append(art)
                placed = True
                break
        if not placed:
            clusters.append({"rep": art, "members": [art], "toks": toks})

    out = []
    for c in clusters:
        rep = dict(c["rep"])
        members = c["members"]
        # Borrow an image from a sibling when the newest item has none
        if not rep.get("image"):
            for m in members:
                if m.get("image"):
                    rep["image"] = m["image"]
                    rep["thumb"] = m.get("thumb") or m["image"]
                    break
        # Longest summary across the cluster is usually the most informative
        best_summary = max((m.get("summary") or "" for m in members), key=len)
        if len(best_summary) > len(rep.get("summary") or ""):
            rep["summary"] = best_summary
        also, seen_src = [], {rep["source"]}
        for m in members:
            if m["source"] in seen_src:
                continue
            seen_src.add(m["source"])
            also.append({"source": m["source"], "link": m["link"], "color": m["color"],
                         "title": m.get("title", ""), "date": m.get("date")})
        rep["also"] = also
        rep["sources"] = [rep["source"]] + [x["source"] for x in also]
        out.append(rep)

    out.sort(key=lambda a: a["date"], reverse=True)
    print(f"  Clustered {len(articles)} articles into {len(out)} stories")
    return out


# Oil & Gas and Finance feeds (Google News queries, OilNOW) return evergreen
# pages and tag/archive pages next to news: keep real, recent stories only.
NEWS_TOPIC_MAX_DAYS = 90
_NEWS_JUNK_TITLE_RE = re.compile(r"^(?:tag|category|archives?)\s*:|^\d{4}\s*[\u2013-]\s*oilnow$|^suriname(?:\s*[\u2013-]\s*offshore energy)?$", re.I)

def _news_recent(articles, days=NEWS_TOPIC_MAX_DAYS):
    cutoff = datetime.now(timezone.utc) - timedelta(days=days)
    out = [a for a in articles
           if a["date"] >= cutoff and not _NEWS_JUNK_TITLE_RE.search(a.get("title") or "")
           and len((a.get("title") or "").split()) >= 3]      # "All", "Suriname": index pages
    if len(out) != len(articles):
        print(f"  News: dropped {len(articles) - len(out)} item(s) older than {days}d or tag pages")
    return out


def _gn_title_pub(entry, title):
    """Google News titles end in " - Publisher". Return (clean title, publisher)."""
    pub = ""
    try:
        pub = (getattr(entry, "source", None) or {}).get("title", "") or ""
    except Exception:
        pub = ""
    if pub and title.endswith(" - " + pub):
        title = title[: -len(pub) - 3].rstrip()
    elif not pub and " - " in title and "news.google." in (getattr(entry, "link", "") or ""):
        title, pub = title.rsplit(" - ", 1)
    return title.strip(), pub.strip()


def fetch_oil_articles():
    """Fetch Oil & Gas articles relevant to Suriname.
    Broad feeds (filter=True) are restricted to articles mentioning Suriname keywords.
    """
    _UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
    articles = []
    for src_feed in OIL_FEEDS:
        try:
            feed  = feedparser.parse(src_feed["url"], agent=_UA)
            if getattr(feed, "status", 200) in (403, 401):
                print(f"  SKIP {src_feed['name']} (oil): HTTP {feed.status} — feed blocks server requests")
                continue
            count = 0
            for entry in feed.entries[:30]:
                title   = strip_tags(getattr(entry, "title", "")).strip()
                title, _pub = _gn_title_pub(entry, title)
                summary = clean_summary(strip_tags(getattr(entry, "summary", "")))
                if "news.google." in src_feed["url"] and (summary.startswith(title) or len(summary) < 40):
                    summary = ""      # Google News "summary" just repeats the title
                # Filter broad feeds to Suriname-relevant articles only
                if src_feed.get("filter"):
                    combined = (title + " " + summary).lower()
                    if not any(kw in combined for kw in _OIL_KEYWORDS):
                        continue
                if len(summary) > 200: summary = summary[:197] + "..."
                link = getattr(entry, "link", "#")
                pub  = parse_date(entry)
                articles.append({
                    "title":   title,
                    "link":    link,
                    "summary": summary,
                    "image":   get_image(entry),
                    "date":    pub,
                    "ago":     time_ago(pub),
                    "source":  src_feed["name"],
                    "color":   src_feed["color"],
                    "pub":     _pub or src_feed["name"],
                    "kind":    "oil",
                })
                count += 1
            print(f"  OK  {src_feed['name']} (oil): {count}")
        except Exception as e:
            print(f"  ERR {src_feed['name']} (oil): {e}")
    articles.sort(key=lambda a: a["date"], reverse=True)
    return _news_recent(articles)

def fetch_finance_articles():
    """Fetch Suriname finance & economy articles from Google News RSS feeds."""
    _UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
    articles = []
    seen = set()
    for src_feed in FINANCE_FEEDS:
        try:
            feed  = feedparser.parse(src_feed["url"], agent=_UA)
            count = 0
            for entry in feed.entries[:20]:
                title   = strip_tags(getattr(entry, "title", "")).strip()
                title, _pub = _gn_title_pub(entry, title)
                summary = clean_summary(strip_tags(getattr(entry, "summary", "")))
                if summary.startswith(title) or len(summary) < 40:
                    summary = ""      # Google News "summary" just repeats the title
                link    = getattr(entry, "link", "#")
                # deduplicate by normalised title
                key = title.lower()[:60]
                if key in seen:
                    continue
                seen.add(key)
                if len(summary) > 200: summary = summary[:197] + "..."
                pub = parse_date(entry)
                articles.append({
                    "title":   title,
                    "link":    link,
                    "summary": summary,
                    "image":   get_image(entry),
                    "date":    pub,
                    "ago":     time_ago(pub),
                    "source":  src_feed["name"],
                    "color":   src_feed["color"],
                    "pub":     _pub or src_feed["name"],
                    "kind":    "finance",
                })
                count += 1
            print(f"  OK  {src_feed['name']} (finance): {count}")
        except Exception as e:
            print(f"  ERR {src_feed['name']} (finance): {e}")
    articles.sort(key=lambda a: a["date"], reverse=True)
    return _news_recent(articles)

def fetch_sports_articles():
    """Fetch Surinamese sport news (De Sport Wekker, category Binnenlands).
    WP REST API first (gives featured images), category RSS as fallback."""
    _UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
    def _clean_title(t):
        t = strip_tags(t).strip()
        return _LEAD_EMOJI_RE.sub("", t).strip() or t
    articles = []
    for src_feed in SPORTS_FEEDS:
        got = 0
        try:
            req = urllib.request.Request(src_feed["api"], headers={"User-Agent": _UA, "Accept": "application/json"})
            with urllib.request.urlopen(req, timeout=25) as r:
                posts = json.loads(r.read().decode("utf-8"))
            for p in posts if isinstance(posts, list) else []:
                title = _clean_title((p.get("title") or {}).get("rendered", ""))
                if not title:
                    continue
                summary = clean_summary(strip_tags((p.get("excerpt") or {}).get("rendered", "")))
                summary = _LEAD_EMOJI_RE.sub("", summary).strip()
                if len(summary) > 200: summary = summary[:197] + "..."
                img = ""
                media = ((p.get("_embedded") or {}).get("wp:featuredmedia") or [{}])[0] or {}
                sizes = (media.get("media_details") or {}).get("sizes") or {}
                for k in ("medium_large", "large", "medium", "full"):
                    if (sizes.get(k) or {}).get("source_url"):
                        img = sizes[k]["source_url"]; break
                img = img or media.get("source_url", "") or ""
                try:
                    pub = datetime.strptime(p.get("date_gmt", ""), "%Y-%m-%dT%H:%M:%S").replace(tzinfo=timezone.utc)
                except Exception:
                    pub = datetime.fromtimestamp(0, tz=timezone.utc)
                articles.append({"title": title, "link": p.get("link", "#"), "summary": summary,
                                 "image": img, "date": pub, "ago": time_ago(pub),
                                 "source": src_feed["name"], "color": src_feed["color"]})
                got += 1
            print(f"  OK  {src_feed['name']} (sports, api): {got}")
        except Exception as e:
            print(f"  WARN {src_feed['name']} (sports, api): {e} — trying RSS")
        if got:
            continue
        try:
            feed = feedparser.parse(src_feed["url"], agent=_UA)
            for entry in feed.entries[:30]:
                title = _clean_title(getattr(entry, "title", ""))
                summary = _LEAD_EMOJI_RE.sub("", clean_summary(strip_tags(getattr(entry, "summary", "")))).strip()
                if len(summary) > 200: summary = summary[:197] + "..."
                pub = parse_date(entry)
                img = get_image(entry)
                if "s.w.org/images/core/emoji" in img: img = ""
                articles.append({"title": title, "link": getattr(entry, "link", "#"), "summary": summary,
                                 "image": img, "date": pub, "ago": time_ago(pub),
                                 "source": src_feed["name"], "color": src_feed["color"]})
                got += 1
            print(f"  OK  {src_feed['name']} (sports, rss): {got}")
        except Exception as e:
            print(f"  ERR {src_feed['name']} (sports): {e}")
    articles.sort(key=lambda a: a["date"], reverse=True)
    return articles

# Last known good rates (15 Oct 2026). Every live CME/CBvS fetch is saved here; when a
# source is down the page shows these (badge "Last known", with the source's own
# timestamp) instead of the hardcoded *_FALLBACK tables, which are months old.
# The hardcoded tables are only used when this file does not exist yet.
# Committed by update.yml (git add data/). live stays False for cached rates, so
# rate history, home_live and the douanekoers check never treat them as fresh.
_RATES_LAST_GOOD_PATH = "data/rates_last_good.json"
LAST_KNOWN_PREFIX = "Last known|"

def _rates_last_good_load(src):
    try:
        with open(_RATES_LAST_GOOD_PATH, encoding="utf-8") as f:
            d = json.load(f).get(src) or {}
        rates = d.get("rates")
        if isinstance(rates, list) and len(rates) >= 2 and all(
                isinstance(r, dict) and r.get("currency") and r.get("buy") and r.get("sell") for r in rates):
            return rates, str(d.get("updated") or "")
    except Exception:
        pass
    return None, ""

def _rates_last_good_save(src, rates, updated):
    try:
        try:
            with open(_RATES_LAST_GOOD_PATH, encoding="utf-8") as f:
                d = json.load(f)
            if not isinstance(d, dict):
                d = {}
        except Exception:
            d = {}
        entry = {"rates": rates, "updated": updated,
                 "fetched_at": datetime.now(SR_TZ).strftime("%Y-%m-%dT%H:%M:%S%z")}
        if (d.get(src) or {}).get("rates") == rates and (d.get(src) or {}).get("updated") == updated:
            return
        d[src] = entry
        os.makedirs("data", exist_ok=True)
        with open(_RATES_LAST_GOOD_PATH, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
    except Exception as e:
        print(f"  !! last-good rates ({src}) not saved: {e}")

def _rates_fallback(src, hardcoded, est_label):
    rates, updated = _rates_last_good_load(src)
    if rates:
        print(f"  {src.upper()}: using last known good rates ({updated})")
        return rates, False, LAST_KNOWN_PREFIX + updated
    return hardcoded, False, est_label

def fetch_cme_rates():
    """
    CME.sr rates via their internal JSON API.
    The homepage renders rates via JS (all values are 0.00 in static HTML),
    so HTML scraping never works. The JS calls POST /Home/GetTodaysExchangeRates/
    which returns a JSON list with cash buy/sell for USD and EUR only.
    BusinessDate param is hardcoded in their JS and ignored server-side.
    """
    try:
        req = urllib.request.Request(
            "https://www.cme.sr/Home/GetTodaysExchangeRates/?BusinessDate=2016-07-25",
            data=b"",
            headers={
                "User-Agent":   "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                "Content-Type": "application/json; charset=utf-8",
                "Accept":       "application/json, text/javascript, */*; q=0.01",
                "Referer":      "https://www.cme.sr/",
                "X-Requested-With": "XMLHttpRequest",
            },
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=20) as r:
            payload = json.loads(r.read().decode("utf-8"))

        if not payload or not isinstance(payload, list):
            raise ValueError(f"Unexpected response: {str(payload)[:200]}")
        v = payload[0]

        rates = [
            {"currency": "USD", "name": "US Dollar", "flag": "🇺🇸",
             "buy":  f"{float(v['BuyUsdExchangeRate']):.2f}",
             "sell": f"{float(v['SaleUsdExchangeRate']):.2f}"},
            {"currency": "EUR", "name": "Euro",      "flag": "🇪🇺",
             "buy":  f"{float(v['BuyEuroExchangeRate']):.2f}",
             "sell": f"{float(v['SaleEuroExchangeRate']):.2f}"},
        ]
        ts = datetime.now(SR_TZ).strftime("%d %b %Y %H:%M SR")
        print(f"  CME: rates live via API ({ts})")
        _rates_last_good_save("cme", rates, f"CME: {ts}")
        return rates, True, f"CME: {ts}"

    except Exception as e:
        print(f"  CME API error: {e}")
        return _rates_fallback("cme", CME_FALLBACK, "Estimated rates (API unavailable)")


def fetch_brent_price():
    """
    Brent Crude front-month futures (BZ=F) via Yahoo Finance chart API.
    Server-side fetch — no CORS issues. Returns (price_usd, updated_str).
    """
    try:
        req = urllib.request.Request(
            "https://query1.finance.yahoo.com/v8/finance/chart/BZ%3DF",
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"}
        )
        with urllib.request.urlopen(req, timeout=10) as r:
            d = json.loads(r.read().decode("utf-8"))
        price = d["chart"]["result"][0]["meta"]["regularMarketPrice"]
        ts = datetime.now(SR_TZ).strftime("%d %b %Y %H:%M SR")
        print(f"  Brent Crude: ${price:.2f}/bbl ({ts})")
        return round(price, 2), ts
    except Exception as e:
        print(f"  Brent fetch error: {e}")
        return None, None

# cbvs.sr challenges traffic from outside Suriname since ~15 Oct 2026 (Cloudflare managed challenge,
# GitHub Actions included). Explore's own relay (Cloudflare Worker esr-cbvs on the Explore account, source
# in ExploreSR/cbvs-worker/) keeps a copy that is refreshed whenever a visitor in Suriname opens a page (the /warm
# ping in PAGE_HEAD), because the Worker then runs in Paramaribo where cbvs.sr answers.
CBVS_RELAY = "https://esr-cbvs.surinamedomains.workers.dev/"
CBVS_RELAY_LIVE_H = 6     # a relay copy younger than this counts as live


def _cbvs_relay_get(path, timeout=25):
    """(bytes, copy datetime or None) from the esr-cbvs relay, or (None, None)."""
    try:
        req = urllib.request.Request(CBVS_RELAY + "?" + urllib.parse.urlencode({"path": path}),
                                     headers={"User-Agent": "exploresuriname-build"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            data, at = r.read(), r.headers.get("x-relay-fetched-at")
        when = None
        if at:
            try:
                when = datetime.fromisoformat(at.replace("Z", "+00:00"))
            except Exception:
                when = None
        return data, when
    except Exception as e:
        print(f"  CBVS relay {path}: {e}")
        return None, None


def fetch_cbvs_rates():
    """
    Scrape the Gewogen Gemiddelde Wisselkoersen from cbvs.sr.
    The page contains multiple tables; we target only <table class="exchange-table">
    which holds the correct market rates. A plain unstyled <table> higher on the page
    contains fixed intervention/ceiling rates (~14 SRD/USD) — we must skip that.
    CBVS uses Dutch decimal notation: 37,365 = 37.365.
    GYD is quoted per 100 units; we divide by 100 to store per-unit.
    """
    fb_map = {r["currency"]: r for r in CBVS_FALLBACK}
    SKIP = {"THE", "FOR", "AND", "SRD", "VAR", "CSS", "DIV", "IMG", "NAV", "GEM", "PER"}

    # cbvs.sr's origin is flaky (Cloudflare 521/523 that often clears within seconds), so the
    # homepage gets one more try at the end before we fall back to the last known rates.
    _blocked = False
    for _n, url in enumerate(["https://www.cbvs.sr/", "https://www.cbvs.sr/statistieken/financiele-markten-statistieken/dagelijkse-publicaties",
                              "https://www.cbvs.sr/", "relay:/"]):
        if _n == 2:
            if _blocked:
                continue          # a challenge does not clear in 4 seconds; go to the relay
            __import__("time").sleep(4)
        _copy_at = None
        try:
            if url.startswith("relay:"):
                _data, _copy_at = _cbvs_relay_get(url[6:])
                if not _data:
                    continue
                raw = _data.decode("utf-8", errors="replace")
                url = "esr-cbvs relay" + (f" (copy of {_copy_at:%Y-%m-%d %H:%M} UTC)" if _copy_at else "")
            else:
                req = urllib.request.Request(url, headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                    "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
                    "Accept-Language": "nl,en;q=0.9",
                })
                try:
                    with urllib.request.urlopen(req, timeout=20) as r:
                        raw = r.read().decode("utf-8", errors="replace")
                except urllib.error.HTTPError as _he:
                    if _he.code in (403, 503):
                        _blocked = True
                    raise

            # Extract only the Gewogen Gemiddelde exchange-table block — skip all other tables
            tbl_m = re.search(r'<table[^>]+class="exchange-table"[^>]*>(.*?)</table>', raw, re.DOTALL | re.IGNORECASE)
            if not tbl_m:
                print(f"  CBVS {url}: exchange-table not found in page")
                continue
            tbl_html = tbl_m.group(1)

            # Pull the CBVS publication timestamp from the header (e.g. "24 april - 15:00u")
            ts_m = re.search(r'(\d{1,2}\s+\w+\s*-\s*\d{1,2}:\d{2}u)', tbl_html)
            cbvs_ts = ts_m.group(1).strip() if ts_m else datetime.now(SR_TZ).strftime("%d %b %Y")

            rates = []
            seen  = set()
            for row in re.findall(r'<tr[^>]*>(.*?)</tr>', tbl_html, re.DOTALL | re.IGNORECASE):
                text = html_lib.unescape(re.sub(r'<[^>]+>', ' ', row)).strip()
                is_per_100 = bool(re.search(r'GYD\s*PER\s*100', text, re.IGNORECASE))
                # Dutch decimal: 37,365 → 37.365  (3 decimal digits after comma)
                text_norm = re.sub(r'(\d),(\d{3})\b', r'\1.\2', text)
                cm = re.search(r'\b([A-Z]{3})\b', text_norm)
                if not cm:
                    continue
                code = cm.group(1)
                if code in SKIP or code in seen:
                    continue
                nums = [n for n in re.findall(r'\b(\d{1,3}\.\d{2,4})\b', text_norm) if 0.01 < float(n) < 10000]
                if len(nums) >= 2:
                    buy_val, sell_val = nums[0], nums[1]  # Giraal Aankoop / Giraal Verkoop
                    if is_per_100:
                        buy_val  = f"{float(buy_val)  / 100:.5f}"
                        sell_val = f"{float(sell_val) / 100:.5f}"
                        code = "GYD"
                    fb = fb_map.get(code, {})
                    rates.append({"currency": code, "name": fb.get("name", code),
                                   "buy": buy_val, "sell": sell_val, "flag": fb.get("flag", "\U0001f4b1")})
                    seen.add(code)

            if len(rates) >= 2:
                _rates_last_good_save("cbvs", rates, f"CBVS: {cbvs_ts}")
                if _copy_at is not None:
                    _age_h = (datetime.now(timezone.utc) - _copy_at).total_seconds() / 3600
                    if _age_h > CBVS_RELAY_LIVE_H:
                        print(f"  CBVS: relay copy is {_age_h:.0f} h old ({cbvs_ts}), shown as last known")
                        return rates, False, LAST_KNOWN_PREFIX + f"CBVS: {cbvs_ts}"
                print(f"  CBVS: {len(rates)} rates live from {url} ({cbvs_ts})")
                return rates, True, f"CBVS: {cbvs_ts}"

        except Exception as e:
            print(f"  CBVS {url}: {e}")

    print("  CBVS: all URLs failed, using fallback")
    return _rates_fallback("cbvs", CBVS_FALLBACK, "Estimated rates (live fetch unavailable)")

# ── Commercial bank rates (Finabank, Hakrinbank, DSB, Republic Bank) ─────────
# Fetched at build time from each bank's own published rate page or endpoint.
# Each bank carries a live flag; on failure we fall back to last-known values.

BANK_RATES_FALLBACK = [
    {"key": "finabank",   "name": "Finabank",      "site": "https://www.finabanknv.com/service-desk/koersen-rates/", "domain": "finabanknv.com",
     "usd": (37.46, 37.82), "eur": (42.76, 43.19)},
    {"key": "hakrinbank", "name": "Hakrinbank",    "site": "https://www.hakrinbank.com/en/private/foreign-exchange/", "domain": "hakrinbank.com",
     "usd": (37.40, 37.82), "eur": (42.65, 43.16)},
    {"key": "dsb",        "name": "DSB Bank",      "site": "https://www.dsb.sr", "domain": "dsb.sr",
     "usd": (37.43, 37.81), "eur": (42.70, 43.13)},
    {"key": "republic",   "name": "Republic Bank", "site": "https://www.republicbanksr.com", "domain": "republicbanksr.com",
     "usd": (37.11, 37.81), "eur": (42.43, 43.13)},
]

def _bank_http_get(url, timeout=20):
    req = urllib.request.Request(url, headers={
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8",
        "Accept-Language": "en,nl;q=0.9",
    })
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8", errors="replace")

def _bank_table_rows(tbl_html):
    """Yield stripped-text cell lists for each <tr> in a table's inner HTML."""
    for row in re.findall(r"<tr[^>]*>(.*?)</tr>", tbl_html, re.DOTALL | re.IGNORECASE):
        yield [html_lib.unescape(re.sub(r"<[^>]+>", " ", c)).strip()
               for c in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", row, re.DOTALL | re.IGNORECASE)]

def _fetch_finabank_rates():
    # Rates page publishes a small table with "USD GIRAAL <aankoop> <verkoop>" rows.
    raw  = _bank_http_get("https://www.finabanknv.com/service-desk/koersen-rates/")
    text = re.sub(r"\s+", " ", html_lib.unescape(re.sub(r"<[^>]+>", " ", raw)))
    usd  = re.search(r"USD\s+GIRAAL\s+([\d.,]+)\s+([\d.,]+)", text, re.IGNORECASE)
    eur  = re.search(r"EUR\s+GIRAAL\s+([\d.,]+)\s+([\d.,]+)", text, re.IGNORECASE)
    if not (usd and eur):
        raise ValueError("GIRAAL rows not found")
    _n = lambda s: float(s.replace(",", "."))
    return (_n(usd.group(1)), _n(usd.group(2))), (_n(eur.group(1)), _n(eur.group(2)))

def _fetch_dsb_rates():
    # DSB publishes a plain JSON endpoint with per-currency buy/sell.
    raw = _bank_http_get("https://service.dsbtools.com/exchange/rates")
    d = json.loads(raw)["valuta"]
    return ((float(d["USD"]["buy"]), float(d["USD"]["sell"])),
            (float(d["EUR"]["buy"]), float(d["EUR"]["sell"])))

def _fetch_hakrinbank_rates():
    # Foreign-exchange page: target the table with Purchase/Sale columns
    # (skip the cross-rates table, which has EUR/USD pairs ~1.1).
    raw = _bank_http_get("https://www.hakrinbank.com/en/private/foreign-exchange/")
    usd = eur = None
    for tbl in re.findall(r"<table[^>]*>(.*?)</table>", raw, re.DOTALL | re.IGNORECASE):
        head = re.sub(r"<[^>]+>", " ", tbl).lower()
        if "purchase" not in head or "sale" not in head:
            continue
        for cells in _bank_table_rows(tbl):
            if len(cells) < 3:
                continue
            code = cells[0].upper()
            try:
                buy, sell = float(cells[1]), float(cells[2])
            except ValueError:
                continue
            if code == "USD":
                usd = (buy, sell)
            elif code in ("EUR", "EURO"):
                eur = (buy, sell)
    if not (usd and eur):
        raise ValueError("Purchase/Sale table not found")
    return usd, eur

def _fetch_republic_rates():
    # Homepage forex table: ABBR. | BUY (CASH) | BUY (SIGHT) | SELL | MID RATE.
    raw = _bank_http_get("https://www.republicbanksr.com/")
    usd = eur = None
    for tbl in re.findall(r"<table[^>]*>(.*?)</table>", raw, re.DOTALL | re.IGNORECASE):
        head = re.sub(r"<[^>]+>", " ", tbl).lower()
        if "abbr" not in head or "sell" not in head:
            continue
        for cells in _bank_table_rows(tbl):
            if len(cells) < 4:
                continue
            code = cells[0].upper().strip(".")
            try:
                buy, sell = float(cells[1]), float(cells[3])
            except ValueError:
                continue
            if code == "USD":
                usd = (buy, sell)
            elif code in ("EUR", "EURO"):
                eur = (buy, sell)
    if not (usd and eur):
        raise ValueError("forex table not found")
    return usd, eur

def fetch_bank_rates():
    """
    USD/EUR buy-sell from four commercial banks, scraped from each bank's own
    published rates (Finabank GIRAAL text, Hakrinbank and Republic rate tables,
    DSB JSON endpoint). Falls back per bank to last-known values on failure.
    """
    fetchers = {
        "finabank":   _fetch_finabank_rates,
        "hakrinbank": _fetch_hakrinbank_rates,
        "dsb":        _fetch_dsb_rates,
        "republic":   _fetch_republic_rates,
    }
    banks = []
    for fb in BANK_RATES_FALLBACK:
        b = dict(fb)
        try:
            usd, eur = fetchers[b["key"]]()
            for pair in (usd, eur):
                if not (5 < pair[0] < 500 and 5 < pair[1] < 500):
                    raise ValueError(f"implausible rates {pair}")
            b["usd"], b["eur"], b["live"] = usd, eur, True
            print(f"  {b['name']}: USD {usd[0]:.2f}/{usd[1]:.2f}  EUR {eur[0]:.2f}/{eur[1]:.2f} (live)")
        except Exception as e:
            b["live"] = False
            print(f"  {b['name']} rates error: {e} (fallback)")
        banks.append(b)
    ts = datetime.now(SR_TZ).strftime("%d %b %Y %H:%M SR")
    return banks, ts


