# ── Utility rail data ───────────────────────────────────────────────────────
# Three numbers the build already has (or can get for one cheap request) so the
# rail costs the visitor nothing: no client-side fetch on every page.
_RAIL: dict = {}

_PBM_WEATHER: dict = {}

def _fetch_paramaribo_weather():
    """One Open-Meteo call for Paramaribo (current + today), cached per build.

    Returns {} on failure. Keys: temp, feels, code, rain_mm, rain_prob (today max),
    uv (today max), tmax, tmin, sunrise, sunset (HH:MM SR), as_of (ISO, API time).
    Feeds the utility rail (temp) and data/home_live.json (homepage weather tile)."""
    if _PBM_WEATHER:
        return _PBM_WEATHER
    try:
        url = ("https://api.open-meteo.com/v1/forecast?latitude=5.8520&longitude=-55.2038"
               "&current=temperature_2m,apparent_temperature,weather_code,precipitation"
               "&daily=temperature_2m_max,temperature_2m_min,uv_index_max,precipitation_probability_max,sunrise,sunset"
               "&forecast_days=1&timezone=America%2FParamaribo")
        req = urllib.request.Request(url, headers={"User-Agent": "ExploreSuriname/1.0"})
        with urllib.request.urlopen(req, timeout=12) as r:
            d = json.loads(r.read().decode("utf-8"))
        cur, day = d.get("current") or {}, d.get("daily") or {}
        def _f(v):
            try:
                return None if v is None else float(v)
            except Exception:
                return None
        def _d0(k):
            v = day.get(k) or []
            return v[0] if v else None
        t = _f(cur.get("temperature_2m"))
        if t is None:
            raise ValueError("no temperature_2m in response")
        _PBM_WEATHER.update({
            "temp": round(t), "feels": (round(_f(cur.get("apparent_temperature"))) if _f(cur.get("apparent_temperature")) is not None else None),
            "code": cur.get("weather_code"), "rain_mm": _f(cur.get("precipitation")),
            "rain_prob": _d0("precipitation_probability_max"), "uv": _f(_d0("uv_index_max")),
            "tmax": (round(_f(_d0("temperature_2m_max"))) if _f(_d0("temperature_2m_max")) is not None else None),
            "tmin": (round(_f(_d0("temperature_2m_min"))) if _f(_d0("temperature_2m_min")) is not None else None),
            "sunrise": (str(_d0("sunrise") or "")[11:16] or None), "sunset": (str(_d0("sunset") or "")[11:16] or None),
            "as_of": ((str(cur.get("time") or "")[:16] + "-03:00") if cur.get("time") else None),
        })
    except Exception as e:
        print(f"  !! Open-Meteo weather failed: {e}")
    return _PBM_WEATHER

def fetch_paramaribo_temp():
    """Current Paramaribo temperature from Open-Meteo. Returns int or None."""
    w = _fetch_paramaribo_weather()
    return w.get("temp") if w else None

_OUTAGE_STALE_H = 10   # update_outages.yml runs every 4 h; one missed run + slack

def _outage_feed_age_h(d):
    """Hours since a scraper wrote its cache, or None when it never said."""
    try:
        ts = d.get("last_updated") or ""
        t = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        if t.tzinfo is None:
            t = t.replace(tzinfo=timezone.utc)
        return (datetime.now(timezone.utc) - t).total_seconds() / 3600
    except Exception:
        return None

def _rail_notice_count():
    """Utility outage notices for today, from the scraped caches.

    Returns (count, fresh, next_planned_iso):
      count            notices that apply to today, from FRESH feeds only
      fresh            True only when BOTH feeds were scraped recently, so the
                       rail may claim "No outages today"; a dead scraper must
                       never turn into a reassurance
      next_planned_iso nearest EBS planned outage in the next 7 days (or "")
    """
    today_d = datetime.now(SR_TZ).date()
    today = today_d.strftime("%Y-%m-%d")
    n, fresh, nxt = 0, True, ""
    try:
        with open("data/ebs_outages.json", encoding="utf-8") as f:
            d = json.load(f)
        age = _outage_feed_age_h(d)
        if age is None or age > _OUTAGE_STALE_H:
            fresh = False
        else:
            for o in d.get("outages", []):
                di = o.get("date_iso") or ""
                if di == today:
                    n += 1
                elif di > today:
                    try:
                        if (datetime.strptime(di, "%Y-%m-%d").date() - today_d).days <= 7 and (not nxt or di < nxt):
                            nxt = di
                    except Exception:
                        pass
    except Exception:
        fresh = False
    try:
        with open("data/swm_outages.json", encoding="utf-8") as f:
            d = json.load(f)
        age = _outage_feed_age_h(d)
        if age is None or age > _OUTAGE_STALE_H:
            fresh = False
        else:
            n += len(d.get("active", []))
    except Exception:
        fresh = False
    return n, fresh, nxt

_RATE_HISTORY_PATH = "data/rate_history.json"
_RATE_HISTORY_DAYS = 400

def record_rate_history(cme_rates, cme_live, cbvs_rates, cbvs_live):
    """One USD/EUR snapshot per Suriname calendar day (added 14 Oct 2026).

    Feeds the homepage "change since yesterday" arrow. Only LIVE fetches are
    recorded (fallback tables would write fiction); the last build of a day
    wins; older than _RATE_HISTORY_DAYS is pruned. Never raises: history is
    a nice-to-have, the build is not."""
    try:
        try:
            with open(_RATE_HISTORY_PATH, encoding="utf-8") as f:
                hist = json.load(f)
        except Exception:
            hist = {}
        days = hist.get("days") if isinstance(hist.get("days"), dict) else {}
        today = datetime.now(SR_TZ).strftime("%Y-%m-%d")
        entry = dict(days.get(today) or {})
        changed = False
        for src, rates, live in (("cme", cme_rates, cme_live), ("cbvs", cbvs_rates, cbvs_live)):
            if not live:
                continue
            snap = {}
            for r in (rates or []):
                if r.get("currency") in ("USD", "EUR"):
                    try:
                        snap[r["currency"]] = [round(float(r["buy"]), 3), round(float(r["sell"]), 3)]
                    except Exception:
                        pass
            if snap and entry.get(src) != snap:
                entry[src] = snap
                changed = True
        if not changed:
            return
        days[today] = entry
        keep = sorted(days)[-_RATE_HISTORY_DAYS:]
        hist = {"days": {d: days[d] for d in keep},
                "note": "USD/EUR [buy, sell] per Suriname day; cme = CME cash, cbvs = CBvS official."}
        os.makedirs("data", exist_ok=True)
        with open(_RATE_HISTORY_PATH, "w", encoding="utf-8") as f:
            json.dump(hist, f, ensure_ascii=False, indent=1)
        print(f"  OK  rate history: {today} recorded ({len(keep)} days kept)")
    except Exception as e:
        print(f"  !! rate history skipped: {e}")

_HOME_LIVE_PATH = "data/home_live.json"

def write_home_live(cme_rates, cme_live, cbvs_rates, cbvs_live, articles, flights_data):
    """data/home_live.json: everything the homepage shows live, in one small file.

    Phase 1 of the homepage freshness programme (14 Oct 2026). Every item carries
    "as_of" (the time the DATA is from, not the build), "ok" (the source answered)
    and "stale_after_h" (after which the homepage must hide it rather than show
    it). The build writes it; the browser re-reads it every few minutes (sw.js
    serves /data/ network-first). Never raises."""
    try:
        now = datetime.now(SR_TZ)
        now_iso = now.isoformat(timespec="minutes")
        items = {}

        # Rates: CME cash (rail/homepage), CBvS official alongside; change vs previous day
        def _pair(rates, cur):
            for r in (rates or []):
                if r.get("currency") == cur:
                    try:
                        return [round(float(r["buy"]), 3), round(float(r["sell"]), 3)]
                    except Exception:
                        return None
            return None
        prev = {}
        try:
            with open(_RATE_HISTORY_PATH, encoding="utf-8") as f:
                _days = (json.load(f).get("days") or {})
            _today = now.strftime("%Y-%m-%d")
            for _d in sorted(_days, reverse=True):
                if _d < _today and (_days[_d].get("cme") or {}).get("USD"):
                    prev = {"date": _d, **_days[_d]["cme"]}
                    break
        except Exception:
            prev = {}
        _hist = []
        try:
            with open(_RATE_HISTORY_PATH, encoding="utf-8") as f:
                _days = (json.load(f).get("days") or {})
            for _d in sorted(_days)[-14:]:
                _u = (_days[_d].get("cme") or {}).get("USD")
                if _u and len(_u) == 2:
                    _hist.append([_d, _u[0]])
        except Exception:
            _hist = []
        items["rates"] = {
            "hist": _hist,
            "ok": bool(cme_live), "as_of": now_iso if cme_live else None,
            "stale_after_h": 74 if now.weekday() >= 4 else 26, "source": "CME",
            "usd": _pair(cme_rates, "USD"), "eur": _pair(cme_rates, "EUR"),
            "prev_date": prev.get("date"), "usd_prev": prev.get("USD"), "eur_prev": prev.get("EUR"),
            "cbvs_ok": bool(cbvs_live), "cbvs_usd": _pair(cbvs_rates, "USD") if cbvs_live else None,
            "cbvs_eur": _pair(cbvs_rates, "EUR") if cbvs_live else None,
        }

        # Weather: the same Open-Meteo call the rail uses
        w = dict(_PBM_WEATHER)
        items["weather"] = {"ok": bool(w), "as_of": w.pop("as_of", None), "stale_after_h": 2, **w}

        # Outages: the rail's own numbers plus the feeds' timestamps
        _ages = []
        for _fn in ("data/ebs_outages.json", "data/swm_outages.json"):
            try:
                with open(_fn, encoding="utf-8") as f:
                    _ages.append(_outage_feed_age_h(json.load(f)))
            except Exception:
                _ages.append(None)
        _age = max([a for a in _ages if a is not None], default=None)
        items["outages"] = {
            "ok": bool(_RAIL.get("notices_fresh")), "stale_after_h": _OUTAGE_STALE_H,
            "as_of": ((now - timedelta(hours=_age)).isoformat(timespec="minutes") if _age is not None else None),
            "today": _RAIL.get("notices"), "next_planned": _RAIL.get("next_planned") or None,
        }

        # Events: resolved by build_events_page() this build
        _he = dict(_HOME_EVENTS)
        _all_up = list(_he.get("upcoming") or [])
        _upc = _all_up[:6]
        _spid = _he.get("spotlight") or ""
        if _spid and not any(u.get("id") == _spid for u in _upc):
            _m = [u for u in _all_up if u.get("id") == _spid]
            if _m:
                _upc = [_m[0]] + _upc[:5]
        items["events"] = {"ok": bool(_he), "as_of": now_iso if _he else None, "stale_after_h": 24,
                           "spotlight": _he.get("spotlight", ""), "weekend": _he.get("weekend"),
                           "next_holiday": _he.get("next_holiday"), "upcoming": _upc}

        # Flights: PBM only on the homepage; the cache carries its own fetch time
        _fl = (flights_data or {}).get("SMJP") or (None, None, None)
        _arr, _dep, _upd = (list(_fl) + [None, None, None])[:3]
        _fetched = None
        try:
            with open("flights_cache.json", encoding="utf-8") as f:
                _fetched = (json.load(f) or {}).get("fetched")
        except Exception:
            pass
        _slim = lambda L: [{k: x.get(k) for k in ("flight", "airline", "iata", "airport", "time", "status")} for x in (L or [])[:4]]
        items["flights"] = {
            "ok": bool(_arr or _dep),
            "as_of": (datetime.fromtimestamp(float(_fetched), SR_TZ).isoformat(timespec="minutes") if _fetched else None),
            "stale_after_h": 8, "updated": _upd, "page": "/flights.html",
            "arrivals": _slim(_arr), "departures": _slim(_dep),
        }

        # News: newest first, as_of = newest article
        _news = []
        for a in (articles or [])[:4]:
            _dt = a.get("date")
            _news.append({"title": a.get("title", ""), "link": a.get("link", ""), "source": a.get("source", ""),
                          "image": "",   # homepage news card stays text-only (17 Oct 2026)
                          "date": (_dt.astimezone(SR_TZ).isoformat(timespec="minutes") if hasattr(_dt, "astimezone") else None)})
        items["news"] = {"ok": bool(_news), "as_of": (_news[0]["date"] if _news else None), "stale_after_h": 24,
                         "page": "/news.html", "items": _news}

        out = {"built": now_iso, "built_epoch": int(now.timestamp()), "tz": "America/Paramaribo",
               "note": "Homepage live feed. as_of = time of the data; hide an item once older than stale_after_h.",
               "items": items}
        os.makedirs("data", exist_ok=True)
        with open(_HOME_LIVE_PATH, "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, separators=(",", ":"))
        _bad = [k for k, v in items.items() if not v.get("ok")]
        print(f"  OK  home_live.json written ({len(items)} items" + (f", not ok: {', '.join(_bad)}" if _bad else "") + ")")
        return out
    except Exception as e:
        print(f"  !! home_live.json skipped: {e}")
        return {}

def build_rail_data(cme_rates):
    """Populate _RAIL before any page is built. Missing items are simply omitted."""
    buy = sell = ""
    for r in (cme_rates or []):
        if r.get("currency") == "USD":
            try:
                buy  = f"{float(r['buy']):.2f}"
                sell = f"{float(r['sell']):.2f}"
            except Exception:
                buy = sell = ""
            break
    _RAIL["usd_buy"]  = buy
    _RAIL["usd_sell"] = sell
    _RAIL["temp"]    = fetch_paramaribo_temp()
    _RAIL["notices"], _RAIL["notices_fresh"], _RAIL["next_planned"] = _rail_notice_count()
    _RAIL["date"]    = datetime.now(SR_TZ).strftime("%a %-d %B")
    _RAIL["iso"]     = datetime.now(SR_TZ).strftime("%Y-%m-%d")
    print(f"  OK  utility rail: USD {buy or 'n/a'}/{sell or 'n/a'}, {_RAIL['temp']}C, "
          f"{_RAIL['notices']} outage notices (feeds fresh: {_RAIL['notices_fresh']}, next planned: {_RAIL['next_planned'] or '-'})")

def util_rail_html(prefix=""):
    """The 34px strip above the nav. Scrolls away with the page by design."""
    left = []
    # Cambio boards show two columns, so the pair reads naturally here. Order and
    # wording match currency.html: "We Buy" is what they pay you, "We Sell" is what
    # you pay them.
    if _RAIL.get("usd_buy") and _RAIL.get("usd_sell"):
        left.append(f'<a href="{prefix}currency.html" title="CME cash rate: we buy / we sell">'
                    f'USD <strong>{_RAIL["usd_buy"]}</strong> / <strong>{_RAIL["usd_sell"]}</strong></a>')
    elif _RAIL.get("usd_sell"):
        left.append(f'<a href="{prefix}currency.html">USD <strong>{_RAIL["usd_sell"]}</strong></a>')
    if _RAIL.get("temp") is not None:
        left.append(f'<a href="{prefix}conditions.html">{_RAIL["temp"]}&deg; Paramaribo</a>')
    # Two fixed strings, count kept outside them, so build_i18n only ever has two
    # segments to carry no matter what the number is on the day.
    # "No outages today" is a promise: it is only made when both scrapers ran
    # recently. A stale feed drops the item instead of reassuring anyone. An
    # upcoming planned outage (next 7 days) is shown instead of "No outages",
    # date through data-srdate so build_i18n localizes it like the rail date.
    _n = _RAIL.get("notices")
    _np = _RAIL.get("next_planned") or ""
    if _n:
        left.append(f'<a href="{prefix}daily-notices.html">'
                    f'<strong>{_n}</strong> Outage notices today</a>')
    elif _n == 0 and _RAIL.get("notices_fresh"):
        if _np:
            try:
                _npd = datetime.strptime(_np, "%Y-%m-%d").strftime("%a %-d %B")
            except Exception:
                _npd = ""
            if _npd:
                left.append(f'<a href="{prefix}daily-notices.html">Planned outage'
                            f' <span data-srdate="{_np}">{_npd}</span></a>')
            else:
                left.append(f'<a href="{prefix}daily-notices.html">No outages today</a>')
        else:
            left.append(f'<a href="{prefix}daily-notices.html">No outages today</a>')
    if not left:
        return ""
    # data-srdate lets build_i18n write the date in Dutch / Spanish.
    right = (f'<span data-srdate="{_RAIL.get("iso", "")}">{_RAIL["date"]}</span>'
             if _RAIL.get("date") else "")
    return (f'<div class="util-rail"><div class="util-in">'
            f'<div class="util-l">{"".join(left)}</div>'
            f'<div class="util-r">{right}</div>'
            f'</div></div>')


def _retired_stub(target):
    """noindex meta-refresh page for a retired URL (build_i18n._STUBS must list it too)."""
    return ('<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1">'
            '<meta name="robots" content="noindex,follow">'
            f'<meta http-equiv="refresh" content="0;url={target}">'
            f'<link rel="canonical" href="{SITE_URL}{target}">'
            '<title>Redirecting&hellip;</title></head><body>'
            f'<p>This page has moved: <a href="{target}">continue here</a>.</p>'
            '</body></html>')


