def _explore_more_html(active):
    """Bottom-of-page 'Keep exploring' card grid linking to the other pillar pages."""
    active_file = (active or "") + ".html"
    cards = ""
    n = 0
    for href, label, tag in _PILLARS:
        if href == active_file:
            continue
        n += 1
        cards += (
            '<a href="' + href + '" class="block bg-white rounded-2xl border border-gray-100 '
            'hover:border-gray-300 hover:shadow-sm transition p-5">'
            '<h3 class="font-semibold text-gray-900 mb-1">' + label + '</h3>'
            '<p class="text-sm text-gray-500 leading-snug">' + tag + '</p>'
            '</a>'
        )
    if not cards:
        return ""
    return (
        '\n<section class="max-w-6xl mx-auto px-5 pb-20" aria-labelledby="explore-more-heading">'
        '\n  <h2 id="explore-more-heading" class="serif text-2xl sm:text-3xl font-bold text-gray-900 mb-2">Keep exploring Suriname</h2>'
        '\n  <p class="text-gray-500 mb-6">More guides to help you plan your trip.</p>'
        # _PILLARS shrank to 5 when Nature merged into Things to Do, so this grid
        # renders 4 cards on a pillar page and 5 elsewhere. Match the column count
        # to the card count so the last row never leaves a hole. Both class names
        # appear literally here because tailwind.config scans this file.
        '\n  <div class="grid grid-cols-2 sm:grid-cols-3 ' +
        ('lg:grid-cols-4' if n <= 4 else 'lg:grid-cols-5') + ' gap-4">'
        + cards +
        '\n  </div>'
        '\n</section>'
    )


def listing_page(title, subtitle, meta_desc, items, cards_html, bg_color="var(--forest)", page_file="", extra_html="", filter_bar="", og_image=None, lcp_image=None, seo_title=None, intro_text="", faq=None, card_count=None, grid_class="listing-grid"):
    _page_active = page_file.replace(".html", "") if page_file else "home"
    page_url = f"{SITE_URL}/{page_file}"
    _og_img = og_image or f"{SITE_URL}/og-image.jpg"
    _seo_title = seo_title or title
    _lcp_preload = f'  <link rel="preload" as="image" href="{lcp_image}" fetchpriority="high">\n' if lcp_image else ""
    _faq_head, _faq_body = _render_faq(faq)
    # Cards rendered, which is not always len(items) — see card_count.
    _n_cards = card_count if card_count is not None else len(items)
    _xlinks = _INTRO_CROSSLINKS.get(_page_active, "")
    _xhtml = ('<p class="xlinks">' + _xlinks + '</p>') if _xlinks else ""
    # Intro copy is SEO text, not wayfinding: it renders below the listings so
    # the grid starts near the top of the page while the words stay indexable.
    _intro_block = ('<section class="cat-about"><h2>About ' + title + '</h2><p>'
                    + intro_text + '</p>' + _xhtml + '</section>') if intro_text else ""
    _cta = ('<a class="cat-cta" href="submit-business.html">'
            '<span aria-hidden="true">+</span> Add your business</a>')
    # The filter bar carries its own bottom margin, so main only needs top
    # padding when there is no bar above it.
    _main_pt = "pt-2" if filter_bar else "pt-8"
    _explore = _explore_more_html(_page_active)
    return f"""{PAGE_HEAD}
  <title>{_seo_title} | Explore Suriname</title>
  <meta name="description" content="{html_lib.escape(meta_desc)}">
  <link rel="canonical" href="{page_url}">
  <meta property="og:type" content="website">
  <meta property="og:site_name" content="Explore Suriname">
  <meta property="og:url" content="{page_url}">
  <meta property="og:title" content="{_seo_title} | Explore Suriname">
  <meta property="og:description" content="{html_lib.escape(meta_desc)}">
  <meta property="og:image" content="{_og_img}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{_seo_title} | Explore Suriname">
  <meta name="twitter:description" content="{html_lib.escape(meta_desc)}">
  <meta name="twitter:image" content="{_og_img}">
  <script type="application/ld+json">
  {{"@context":"https://schema.org","@type":"ItemList","name":"{title}","url":"{page_url}","numberOfItems":{len(items)},"itemListElement":[{",".join(
    '{"@type":"ListItem","position":' + str(i+1) + ',"name":' + __import__("json").dumps(it.get("name","")) + ',"url":"' + _itemlist_url(it) + '"}' for i,it in enumerate(items[:20])
  )}]}}
  </script>
  <script type="application/ld+json">
  {{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{{"@type":"ListItem","position":1,"name":"Home","item":"{SITE_URL}/"}},{{"@type":"ListItem","position":2,"name":"{title}","item":"{page_url}"}}]}}
  </script>
  <script type="application/ld+json">
  {{"@context":"https://schema.org","@type":"WebPage","name":"{_seo_title} | Explore Suriname","url":"{page_url}","dateModified":"{datetime.now(SR_TZ).strftime('%Y-%m-%d')}","about":{{"@type":"Place","name":"Suriname","addressCountry":"SR"}},"isPartOf":{{"@type":"WebSite","name":"Explore Suriname","url":"{SITE_URL}/"}}}}
  </script>{_faq_head}
{_lcp_preload}</head>
<body class="bg-paper overflow-x-hidden">
{nav_html(_page_active)}
<div class="cat-hero cat-hero-compact" style="--cat:{bg_color}">
  <div class="cat-hero-in">
    <nav class="cat-crumb" aria-label="Breadcrumb">
      <a href="./">Home</a><span aria-hidden="true">&rsaquo;</span><span>{title}</span>
    </nav>
    <div class="cat-row">
      <div>
        <h1 class="serif">{title} <span class="h1-count">{_n_cards}</span></h1>
        <p class="cat-sub">{subtitle}</p>
      </div>
      {_cta}
    </div>
  </div>
</div>
{filter_bar}
<main class="max-w-6xl mx-auto px-5 {_main_pt} pb-24">
  <div id="result-count" class="text-sm text-gray-400 mb-4 font-medium">{_n_cards} results</div>
  <div class="{grid_class}">
    {cards_html}
  </div>
  {extra_html}
  {_faq_body}
  {_intro_block}
</main>
{_explore}
{footer_html()}
</body>
</html>"""

# -- Page builders ------------------------------------------------------------

def _featured_order(lst):
    """Float admin-featured listings to the top of a category grid.

    Featured slugs and their priority come from the admin panel (_ADMIN_FEATURED);
    nothing is hardcoded here. Within the featured block: lower priority number
    first, then alphabetical. Everything else keeps its existing order.
    """
    if not _ADMIN_FEATURED:
        return list(lst)
    feat = sorted(
        (b for b in lst if b["slug"] in _ADMIN_FEATURED),
        key=lambda b: (_ADMIN_FEATURED[b["slug"]], b.get("name", "").lower()),
    )
    rest = [b for b in lst if b["slug"] not in _ADMIN_FEATURED]
    return feat + rest


