def _la_cta(href, icon, label, kind="wa"):
    return ('<a href="' + html_lib.escape(href) + '" target="_blank" rel="noopener" class="la-cta la-' + kind + '">'
            + _LA_SVG[icon] + '<span>' + label + '</span></a>')


def _lr(icon, value_html, href=None, act=None, link=False, newtab=True, aria=None, cls=""):
    """One contact row. With href the whole row is the link; act adds the round
    action icon on the right (decorative: the row itself carries the label)."""
    inner = ('<span class="lr-i">' + _LA_SVG[icon] + '</span>'
             '<span class="lr-v' + (' lr-lk' if link else '') + '">' + value_html + '</span>'
             + ('<span class="lr-a" aria-hidden="true">' + _LA_SVG[act] + '</span>' if act else ''))
    klass = 'lr' + (' ' + cls if cls else '')
    if not href:
        return '<div class="' + klass + '">' + inner + '</div>'
    return ('<a href="' + html_lib.escape(href) + '"' + (' target="_blank" rel="noopener"' if newtab else '')
            + (' aria-label="' + html_lib.escape(aria, quote=True) + '"' if aria else '')
            + ' class="' + klass + '">' + inner + '</a>')


def _la_domain(url):
    d = re.sub(r"^https?://", "", (url or "").strip(), flags=re.I)
    d = re.sub(r"^www\.", "", d, flags=re.I)
    return d.split("?")[0].split("#")[0].rstrip("/")


def _la_list(rows):
    rows = [r for r in rows if r]
    return '<div class="lr-list">' + "".join(rows) + '</div>' if rows else ""


def _la_call_href(phone):
    """tel: target only when it looks like one dialable number (a field holding
    two numbers would otherwise glue them into one bogus tel: link)."""
    t = _tel_href(phone or "")
    return t if re.fullmatch(r"\+\d{9,13}", t) else ""


def _dir_link(search_link):
    """Google Maps search URL -> directions URL (opens routing / the Maps app)."""
    return search_link.replace("/maps/search/?api=1&query=", "/maps/dir/?api=1&destination=")


def _branch_info(bslug):
    """One address of a chain, using the same fallbacks a listing page uses."""
    b = _make_biz(bslug)
    if not b:
        return None
    osm     = _ENRICHMENTS.get(bslug, {})
    address = b.get("address") or osm.get("address") or ""
    area    = b.get("area") or "Paramaribo"
    q = urllib.parse.quote(b["name"] + ", " + (address or area + ", Suriname"))
    return {
        "slug":    bslug,
        "name":    b["name"],
        "area":    area,
        "address": address,
        "phone":   b.get("phone") or osm.get("phone") or "",
        "hours":   _MANUAL_HOURS.get(bslug) or osm.get("opening_hours") or "",
        "maps_embed": "https://maps.google.com/maps?q=" + q + "&output=embed&hl=en",
        "maps_link":  "https://www.google.com/maps/search/?api=1&query=" + q,
    }


def _chain_block(brand):
    """Chips + one panel per address for a brand's hub page.

    Every panel is rendered server side and all but the active one is hidden, so
    switching address needs no data round trip and nothing depends on JSON that
    could break on an apostrophe. Only the map iframe is swapped, which keeps
    the page to a single embed instead of one per branch.
    """
    mem = [i for i in (_branch_info(s) for s in _CHAIN_GROUPS.get(brand, [])) if i]
    if len(mem) < 2:
        return None

    def row(icon, content):
        return ('<div class="flex items-start gap-3 py-3 border-b border-gray-100 last:border-0">'
                '<span class="text-xl shrink-0 mt-0.5">' + icon + '</span>'
                '<span class="text-gray-700 text-sm leading-relaxed">' + content + '</span>'
                '</div>')

    chips, panels = [], []
    for i, m in enumerate(mem):
        label = html_lib.escape(_branch_label(brand, m))
        # An anchor, not a button: crawlers and no-JS visitors follow it to that
        # branch's own page, everyone else gets the inline swap and stays put.
        chips.append('<a href="../' + m["slug"] + '/" class="branch-chip dist-chip' +
                     (' dist-chip-active' if i == 0 else '') +
                     '" onclick="return esrBranch(' + str(i) + ',this)">' + label + '</a>')

        _dl   = _dir_link(m["maps_link"])
        _call = _la_call_href(m["phone"])
        wa    = _wa_number(m["phone"])
        _addr = m["address"] or (m["area"] + ", Suriname")
        _rows = [_lr("pin", html_lib.escape(_addr), _dl, "nav", aria="Directions to " + _addr)]
        if m["phone"]:
            _rows.append(_lr("phone", html_lib.escape(m["phone"]), ("tel:" + _call) if _call else None,
                             "phone" if _call else None, link=True, newtab=False))
        if m["hours"]:
            _h = (html_lib.escape(m["hours"]).replace("Mo", "Mon").replace("Tu", "Tue")
                  .replace("We", "Wed").replace("Th", "Thu").replace("Fr", "Fri")
                  .replace("Sa", "Sat").replace("Su", "Sun").replace("; ", "<br>"))
            _rows.append(_lr("clock", _h))
        btns = ((_la_cta("https://wa.me/" + wa, "wa", "Chat on WhatsApp") if wa else "")
                + _la_list(_rows))
        panels.append('<div class="branch-panel' + ('' if i == 0 else ' hidden') +
                      '" id="esr-bp-' + str(i) + '" data-map="' +
                      html_lib.escape(m["maps_embed"], quote=True) + '" data-name="' +
                      html_lib.escape(m["name"], quote=True) + '">' +
                      _LA_CSS + btns + '</div>')

    script = ('<script>function esrBranch(i,btn){'
              'var c=document.querySelectorAll(".branch-chip");'
              'for(var k=0;k<c.length;k++){c[k].classList.remove("dist-chip-active");}'
              'btn.classList.add("dist-chip-active");'
              'var p=document.querySelectorAll(".branch-panel");'
              'for(var j=0;j<p.length;j++){p[j].classList.toggle("hidden",j!==i);}'
              'var a=document.getElementById("esr-bp-"+i);if(!a){return false;}'
              'var f=document.getElementById("esr-branch-map");'
              'if(f&&a.getAttribute("data-map")){f.src=a.getAttribute("data-map");}'
              'var h=document.getElementById("esr-info-title");'
              'if(h&&a.getAttribute("data-name")){h.textContent=a.getAttribute("data-name");}'
              'return false;}</script>')

    def link_row(active_slug):
        """The same chip row for a branch page: every chip is a link, the chip
        for the page you are on is the active one. Chips never disappear."""
        out = []
        for m in mem:
            lbl = html_lib.escape(_branch_label(brand, m))
            if m["slug"] == active_slug:
                out.append('<span class="dist-chip dist-chip-active" aria-current="page">'
                           + lbl + '</span>')
            else:
                out.append('<a href="../' + m["slug"] + '/" class="dist-chip">' + lbl + '</a>')
        return ('<h2 class="text-lg font-bold text-gray-900 mb-2">'
                + html_lib.escape(brand) + ' locations</h2>'
                '<p class="text-gray-500 text-sm mb-3">' + str(len(mem)) + ' locations in Suriname. '
                'Tap another one to see its address, opening hours and directions.</p>'
                '<div class="flex flex-wrap gap-2 mb-6">' + "".join(out) + '</div>')

    chips_html = ('<h2 class="text-lg font-bold text-gray-900 mb-2">Locations</h2>'
                  '<p class="text-gray-500 text-sm mb-3">Pick a location to see its address, '
                  'opening hours and directions.</p>'
                  '<div class="flex flex-wrap gap-2 mb-6">' + "".join(chips) + '</div>')

    return {"count": len(mem), "chips": chips_html, "panels": "".join(panels),
            "first_map": mem[0]["maps_embed"], "script": script, "link_row": link_row,
            "first_name": mem[0]["name"], "areas": sorted({m["area"] for m in mem})}


