# build_crossword_page() — to be inserted into generate.py
def build_crossword_page():
    """Switi Mini - daily Surinaamse kruiswoord. Serves today's mini by date
    rotation over a premade, human-approvable backlog (data/crossword_minis.json),
    with a browse control for earlier minis. Bilingual NL/EN clues, solve payoff."""
    import json as _json
    try:
        with open("data/crossword_minis.json", encoding="utf-8") as _f:
            _puz = _json.load(_f).get("puzzles", [])
    except Exception:
        _puz = []
    today = datetime.now(SR_TZ).date()
    _data = _json.dumps(_puz, ensure_ascii=False)
    _n = len(_puz)
    # today's puzzle: mirror the client-side date rotation so crawlers get fresh content
    _epoch = datetime(2026, 6, 22).date()
    _today_idx = (max(0, (today - _epoch).days) % _n) if _n else 0
    _today_puz = _puz[_today_idx] if _puz else {}
    _today_no = _today_puz.get("no", _today_idx + 1)

    # share image + structured data (@graph: WebPage + BreadcrumbList + Game)
    _ogimg = SITE_URL + "/images/crossword-og.jpg"
    _graph = _ld_safe(_json.dumps({"@context": "https://schema.org", "@graph": [
        {"@type": "WebPage", "@id": SITE_URL + "/crossword.html#webpage",
         "url": SITE_URL + "/crossword.html",
         "name": "Switi Mini: Surinaamse kruiswoord",
         "description": "A free daily crossword in Surinamese words (Sranan Tongo and Surinaams-Nederlands) with Dutch and English clues, in sizes from 5x5 to 11x11. New puzzle every day.",
         "isPartOf": {"@type": "WebSite", "name": "Explore Suriname", "url": SITE_URL + "/"},
         "primaryImageOfPage": _ogimg,
         "breadcrumb": {"@id": SITE_URL + "/crossword.html#breadcrumb"},
         "mainEntity": {"@id": SITE_URL + "/crossword.html#game"},
         "datePublished": "2026-06-22", "dateModified": today.isoformat(),
         "isAccessibleForFree": True},
        {"@type": "BreadcrumbList", "@id": SITE_URL + "/crossword.html#breadcrumb",
         "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": SITE_URL + "/"},
            {"@type": "ListItem", "position": 2, "name": "Switi Mini Crossword", "item": SITE_URL + "/crossword.html"}]},
        {"@type": "Game", "@id": SITE_URL + "/crossword.html#game",
         "name": "Switi Mini", "url": SITE_URL + "/crossword.html",
         "description": "A daily crossword built entirely from Sranan Tongo and Surinaams-Nederlands words, in sizes from 5x5 to 11x11, with clues in Dutch and English.",
         "genre": "Crossword puzzle", "gamePlatform": "Web browser",
         "inLanguage": ["nl", "en"], "isAccessibleForFree": True, "image": _ogimg,
         "publisher": {"@type": "Organization", "name": "Explore Suriname", "url": SITE_URL + "/"}}
    ]}, ensure_ascii=False))

    # FAQ: visible Q&A + FAQPage schema from one source (site _render_faq helper)
    _faq = [
        ("What is Switi Mini?", "Switi Mini is a free daily crossword from Explore Suriname. Every puzzle is built from Surinamese words (Sranan Tongo and Surinaams-Nederlands), with clues you can read in Dutch or English."),
        ("How big are the puzzles?", "The size changes from day to day. Most days are a quick 5x5. Every few days the grid steps up to a 7x7 or 9x9, and once in the rotation there is a full 11x11 holding more than forty answers. Today's size is shown next to the date above the grid."),
        ("Is Switi Mini free to play?", "Yes. Switi Mini is completely free, needs no account and no app. It runs in any browser on phone or desktop, and can be installed as a web app."),
        ("How often is there a new puzzle?", "A new Switi Mini is published every day. You can also step back to earlier days' puzzles using the arrows above the grid."),
        ("What language are the clues in?", "Each clue is written in both Dutch and English. Tap NL or EN to switch. A small tag (SR or SN) shows whether the answer is a Sranan Tongo or Surinaams-Nederlands word."),
        ("Where do the words come from?", "Every answer is a real Surinamese word attested in the dictionaries of Sranan Tongo and Surinaams-Nederlands, so each solve teaches you a little more of the language."),
        ("Do I need to download anything?", "No download is required. Switi Mini runs in your browser. On a phone you can add it to your home screen for one-tap access."),
    ]
    _faq_head, _faq_body = _render_faq(_faq)

    # About + How to play (evergreen, always-visible crawlable content)
    _about_html = (
        '<section class="max-w-3xl mx-auto px-4 mt-16" aria-labelledby="about-heading">'
        '<h2 id="about-heading" class="serif text-2xl sm:text-3xl font-bold text-gray-900 mb-4">About Switi Mini</h2>'
        '<p class="text-gray-600 leading-relaxed mb-4">Switi Mini is a free daily <strong>Surinaamse kruiswoord</strong> built entirely from Surinamese words. Every answer is a word from <strong>Sranan Tongo</strong> or <strong>Surinaams-Nederlands</strong>, attested in the dictionaries, so each puzzle is a small, playful way to learn the language of Suriname.</p>'
        '<p class="text-gray-600 leading-relaxed mb-4">The grid changes shape and size from day to day. Most days bring a quick 5&#215;5, and every few days it steps up to a 7&#215;7 or 9&#215;9. Once in the rotation there is a full 11&#215;11 with more than forty answers. Today&#8217;s size is shown next to the date above the grid.</p>'
        '<p class="text-gray-600 leading-relaxed mb-4">A new puzzle goes live every day. Clues come in both <strong>Dutch and English</strong> (tap NL or EN to switch), and a tag on each clue tells you whether the answer is Sranan Tongo (SR) or Surinaams-Nederlands (SN). Solve the grid and Switi Mini reveals what every word means, so you finish a few words richer than you started.</p>'
        '<h2 class="serif text-2xl sm:text-3xl font-bold text-gray-900 mb-4 mt-10">How to play</h2>'
        '<ol class="text-gray-600 leading-relaxed space-y-2 list-decimal pl-5">'
        '<li>Tap any square or clue to begin, then type your answer. Tap a cell again to switch between across and down.</li>'
        '<li>Use <strong>Check</strong> to test your letters, or <strong>Reveal word</strong> when you are stuck.</li>'
        '<li>Switch the clues between Dutch and English with the NL / EN toggle.</li>'
        '<li>Use the arrows above the grid to play earlier days\' puzzles.</li>'
        '<li>Finish the grid to see the meaning of every word, plus your solve time to share.</li>'
        '</ol>'
        '<p class="text-gray-600 leading-relaxed mt-6">More daily play: try <a class="underline font-semibold" style="color:#1B4332" href="quiz.html">Sabi Suriname</a>, our five-question daily quiz about Suriname.</p>'
        '</section>'
    )

    # today's clues, server-rendered for no-JS crawlers/users (clues only, no answers)
    def _cw_clue_list(_d):
        items = ""
        for e in sorted([x for x in _today_puz.get("entries", []) if x.get("dir") == _d],
                        key=lambda x: x.get("num", 0)):
            items += ('<li><b>' + str(e.get("num", "")) + '.</b> '
                      + html_lib.escape(e.get("clue_nl", ""))
                      + ' <span class="text-gray-400">(' + html_lib.escape(e.get("lang", "")) + ')</span> '
                      + '<span class="text-gray-500">' + html_lib.escape(e.get("clue_en", "")) + '</span></li>')
        return items
    if _today_puz.get("entries"):
        _today_clues_html = (
            '<noscript><section class="max-w-2xl mx-auto px-4 mt-6" aria-label="Today\'s Switi Mini clues">'
            '<h2 class="serif text-xl font-bold text-gray-900 mb-2">Today&#8217;s Switi Mini (#' + str(_today_no) + ')</h2>'
            '<p class="text-sm text-gray-500 mb-4">The interactive grid needs JavaScript. Here are today&#8217;s clues; every answer is a Sranan Tongo or Surinaams-Nederlands word.</p>'
            '<h3 class="font-bold text-gray-900 mt-4 mb-1">Horizontaal / Across</h3><ol class="text-sm text-gray-600 space-y-1 pl-1">' + _cw_clue_list("A") + '</ol>'
            '<h3 class="font-bold text-gray-900 mt-4 mb-1">Verticaal / Down</h3><ol class="text-sm text-gray-600 space-y-1 pl-1">' + _cw_clue_list("D") + '</ol>'
            '</section></noscript>'
        )
    else:
        _today_clues_html = ""
    head = f"""{PAGE_HEAD}
  <title>Switi Mini | Surinaamse kruiswoord | Explore Suriname</title>
  <meta name="description" content="Switi Mini: a free daily crossword in Surinamese words (Sranan Tongo and Surinaams-Nederlands), in grids from 5x5 to 11x11, with clues in Dutch and English. New puzzle every day.">
  <link rel="canonical" href="{SITE_URL}/crossword.html">
  <meta property="og:type" content="website">
  <meta property="og:site_name" content="Explore Suriname">
  <meta property="og:url" content="{SITE_URL}/crossword.html">
  <meta property="og:title" content="Switi Mini: Surinaamse kruiswoord">
  <meta property="og:description" content="A free daily mini crossword in Sranan Tongo and Surinaams-Nederlands, clues in Dutch and English.">
  <meta property="og:image" content="{_ogimg}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:image:alt" content="Switi Mini, a daily Surinamese mini crossword from Explore Suriname">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="Switi Mini: Surinaamse kruiswoord">
  <meta name="twitter:description" content="A free daily mini crossword in Sranan Tongo and Surinaams-Nederlands, clues in Dutch and English.">
  <meta name="twitter:image" content="{_ogimg}">
  <script type="application/ld+json">
  {_graph}
  </script>{_faq_head}
  <style>
  #cw{{--g:#1B4332;--t:#E76F51;--m:#D8F3DC;--sel:#ffe08a;--word:#cde7d6;--bad:#f3c7bd;--line:#cfdbd3}}
  #cw .lang{{display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden;font-size:12px;font-weight:700}}
  #cw .lang button{{border:0;background:#fff;color:#6b7a72;padding:6px 12px;cursor:pointer}}
  #cw .lang button.on{{background:var(--g);color:#fff}}
  #cw .timer{{font-variant-numeric:tabular-nums;font-weight:700;color:#6b7a72;font-size:15px;min-width:48px;text-align:right}}
  #cw .cluebar{{display:flex;align-items:center;gap:8px;background:var(--m);border-radius:14px;padding:12px 8px;margin:14px 0}}
  #cw .cluebar .nav{{border:0;background:transparent;font-size:22px;color:var(--g);cursor:pointer;padding:0 8px;line-height:1}}
  #cw .cluebar .txt{{flex:1;font-size:16px;font-weight:600;text-align:center;color:#1d2421}}
  #cw .cluebar .tag{{font-size:10px;font-weight:700;background:#fff;color:var(--g);border-radius:6px;padding:2px 6px;margin-left:4px}}
  #cw table.cwgrid{{display:table;border-collapse:collapse;margin:0 auto;touch-action:manipulation}}
  #cw{{--cell:58px;--cellfs:26px;--cellnum:10px}}
  #cw table.cwgrid td{{display:table-cell;width:var(--cell);height:var(--cell);border:1px solid var(--line);text-align:center;vertical-align:middle;position:relative;font-size:var(--cellfs);font-weight:700;text-transform:uppercase;cursor:pointer;user-select:none;background:#fff;color:#1d2421}}
  #cw table.cwgrid td.cwblock{{background:var(--g);border-color:var(--g);cursor:default}}
  #cw table.cwgrid td.word{{background:var(--word)}}
  #cw table.cwgrid td.sel{{background:var(--sel)}}
  #cw table.cwgrid td.bad{{background:var(--bad)}}
  #cw table.cwgrid td .n{{position:absolute;top:1px;left:2px;font-size:var(--cellnum);font-weight:700;color:#6b7a72;line-height:1}}
  #cw .sizebadge{{font-size:11px;font-weight:800;color:var(--g);background:var(--m);border-radius:6px;padding:3px 7px;letter-spacing:.5px}}
  #cw .ctrls{{display:flex;gap:8px;justify-content:center;margin:14px 0}}
  #cw .ctrls button{{border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px 16px;font-size:13px;font-weight:700;color:var(--g);cursor:pointer}}
  #cw .clues{{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:10px}}
  #cw .clues h3{{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#6b7a72;margin:0 0 6px}}
  #cw .clues ol{{list-style:none;margin:0;padding:0}}
  #cw .clues li{{display:flex;gap:6px;padding:6px;border-radius:8px;font-size:14px;cursor:pointer;line-height:1.3}}
  #cw .clues li.on{{background:var(--m)}}
  #cw .clues li b{{color:var(--g);min-width:15px}}
  #cw-kb{{position:fixed;left:0;right:0;bottom:0;background:#e9efec;border-top:1px solid var(--line);padding:7px 5px calc(7px + env(safe-area-inset-bottom));display:none;z-index:40}}
  #cw-kb .krow{{display:flex;justify-content:center;gap:4px;margin:3px 0}}
  #cw-kb button{{flex:1;max-width:34px;height:46px;border:0;border-radius:7px;background:#fff;font-size:17px;font-weight:700;color:#1d2421;box-shadow:0 1px 0 rgba(0,0,0,.18);cursor:pointer}}
  #cw-kb button.wide{{max-width:64px;font-size:13px}}
  #cwmodal{{position:fixed;inset:0;background:rgba(20,30,25,.55);display:none;align-items:center;justify-content:center;padding:18px;z-index:50}}
  #cwmodal .card{{background:#fff;border-radius:18px;max-width:440px;width:100%;padding:22px;max-height:86vh;overflow:auto}}
  #cwmodal h3{{margin:0;color:var(--g);font-size:22px}}
  #cwmodal .time{{font-size:32px;font-weight:800;color:var(--t);font-variant-numeric:tabular-nums}}
  #cwmodal .lead{{color:#6b7a72;font-size:14px;margin:4px 0 14px}}
  #cwmodal ul{{list-style:none;margin:0;padding:0}}
  #cwmodal li{{display:flex;align-items:baseline;gap:8px;padding:7px 0;border-top:1px solid var(--line);font-size:14px}}
  #cwmodal li .w{{font-weight:800;color:var(--g);min-width:62px;text-transform:lowercase}}
  #cwmodal li .tag{{font-size:9px;font-weight:700;background:var(--m);color:var(--g);border-radius:5px;padding:1px 5px}}
  #cwmodal .btns{{display:flex;gap:8px;margin-top:16px}}
  #cwmodal .btns button{{flex:1;border:0;border-radius:10px;padding:12px;font-weight:800;font-size:14px;cursor:pointer}}
  #cwmodal .share{{background:var(--g);color:#fff}} #cwmodal .again{{background:var(--m);color:var(--g)}}
  #cwfx{{position:fixed;inset:0;pointer-events:none;z-index:45;display:none}}
  </style>
</head>"""
